//! chap-core's own outputs for its baselines, on two small datasets (monthly and weekly),
//! generated by `scripts/gen_baseline_fixtures.py`. The chapkit-rs ports are checked against them.

use std::collections::HashMap;
use std::time::Instant;

use chapkit::{Checkpoint, DataFrame, Model, Period, PredictInput, RunInfo, TrainInput, cols};
use serde::Deserialize;

/// A fixture: the data, and chap-core's predictions per model keyed `location|period`.
#[derive(Deserialize)]
pub struct Fixture {
    pub train: DataFrame,
    pub historic: DataFrame,
    pub future: DataFrame,
    #[serde(default)]
    pub predictions: HashMap<String, HashMap<String, Vec<f64>>>,
}

type BoxError = Box<dyn std::error::Error>;

impl Fixture {
    /// Load `monthly` or `weekly`.
    pub fn load(case: &str) -> Result<Self, BoxError> {
        let path = format!(
            "{}/fixtures/baselines_{case}.json",
            env!("CARGO_MANIFEST_DIR")
        );
        Self::from_file(path)
    }

    /// Load a fixture file in this format from anywhere (another crate's own fixtures).
    pub fn from_file(path: impl AsRef<std::path::Path>) -> Result<Self, BoxError> {
        Ok(serde_json::from_str(&std::fs::read_to_string(path)?)?)
    }

    /// The monthly fixture: 3 locations plus one unseen in training, 40 months.
    pub fn monthly() -> Result<Self, BoxError> {
        Self::load("monthly")
    }
}

/// How closely a port's samples must match chap-core's.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Match {
    /// Bit for bit: the same `f64` (`to_bits()` equality).
    Exact,
    /// At most this many representable `f64`s apart (units in the last place), for calculations
    /// that call the platform's `exp` and `ln`: numpy and Rust both take them from the C library,
    /// whose last bit differs between platforms (macOS and Linux), so chap-core's own output does.
    Ulps(u64),
    /// At most this far apart relative to the sample, floored at one case
    /// (`|got - want| <= tol * max(|want|, 1)`), for calculations whose last-bit differences
    /// between C libraries are amplified (e.g. `expm1` of a scaled `log1p`), where a ULP count
    /// overstates the difference near zero.
    Relative(f64),
}

impl Match {
    fn accepts(self, got: f64, want: f64) -> bool {
        if got.to_bits() == want.to_bits() {
            return true;
        }
        match self {
            Match::Exact => false,
            Match::Ulps(n) => {
                got.is_finite()
                    && want.is_finite()
                    && got.is_sign_negative() == want.is_sign_negative()
                    && got.to_bits().abs_diff(want.to_bits()) <= n
            }
            Match::Relative(tol) => (got - want).abs() <= tol * want.abs().max(1.0),
        }
    }
}

/// Train and predict `model` on fixture `case` and compare with chap-core's output for `name`,
/// sample by sample, as closely as `matching` asks.
pub fn check_parity<M: Model>(
    case: &str,
    name: &str,
    model: &M,
    config: &M::Config,
    matching: Match,
) -> Result<(), BoxError> {
    check_parity_on(&Fixture::load(case)?, case, name, model, config, matching)
}

/// [`check_parity`] on a fixture already loaded; `case` only labels the errors.
pub fn check_parity_on<M: Model>(
    fx: &Fixture,
    case: &str,
    name: &str,
    model: &M,
    config: &M::Config,
    matching: Match,
) -> Result<(), BoxError> {
    let run = RunInfo::with_periods(3);
    let trained = model.train(config, TrainInput::new(&fx.train, &run, None))?;
    let pred = model.predict(
        &trained,
        config,
        PredictInput::new(&fx.historic, &fx.future, &run, None),
    )?;
    // chap-core keys periods by id (`202105`, `2021W15`); normalise both sides through `Period`.
    let key = |loc: &str, tp: &str| -> Result<String, BoxError> {
        let p = Period::parse(tp).ok_or_else(|| format!("bad period {tp}"))?;
        Ok(format!("{loc}|{p}"))
    };
    let mut expected: HashMap<String, &Vec<f64>> = HashMap::new();
    for (k, v) in fx
        .predictions
        .get(name)
        .ok_or_else(|| format!("no {name} in fixture"))?
    {
        let (l, t) = k.split_once('|').ok_or("bad fixture key")?;
        expected.insert(key(l, t)?, v);
    }
    if pred.n_rows() != expected.len() {
        return Err(format!(
            "{case}/{name}: {} rows, chap-core has {}",
            pred.n_rows(),
            expected.len()
        )
        .into());
    }
    let (tp, loc) = (
        pred.require(cols::TIME_PERIOD)?,
        pred.require(cols::LOCATION)?,
    );
    // Every mismatch is counted, and the largest one reported.
    let (mut mismatches, mut worst, mut worst_at) = (0usize, 0.0f64, String::new());
    for row in 0..pred.n_rows() {
        let k = key(
            loc.str_at(row).unwrap_or_default(),
            tp.str_at(row).unwrap_or_default(),
        )?;
        let want = expected
            .get(&k)
            .ok_or_else(|| format!("{case}/{name}: unexpected row {k}"))?;
        for (i, w) in want.iter().enumerate() {
            let got = pred
                .column(&cols::sample(i))
                .and_then(|c| c.f64_at(row))
                .ok_or_else(|| format!("{case}/{name} {k}: missing sample_{i}"))?;
            if !matching.accepts(got, *w) {
                mismatches += 1;
                let difference = (got - w).abs();
                if mismatches == 1 || difference > worst {
                    worst = difference;
                    worst_at = format!("{k} sample_{i}: got {got:e}, chap-core {w:e}");
                }
            }
        }
    }
    if mismatches > 0 {
        return Err(format!(
            "{case}/{name}: {mismatches} samples differ, largest by {worst:e} at {worst_at}"
        )
        .into());
    }
    Ok(())
}

/// Checkpoint round trip on the monthly fixture (see `chapkit::testing::checkpoint_round_trip`).
pub fn checkpoint_round_trip<M: Model>(
    model: &M,
    config: &M::Config,
) -> Result<Checkpoint, BoxError> {
    let fx = Fixture::monthly()?;
    let run = RunInfo::with_periods(6);
    Ok(chapkit::testing::checkpoint_round_trip(
        model,
        config,
        &fx.train,
        &fx.historic,
        &fx.future,
        &run,
    )?)
}

/// Train and predict once on the monthly fixture; print the timings and each row's median. With
/// `DEMO_OUTPUT=<file>`, also write the prediction table there as chapkit JSON (used for the book's figures).
pub fn demo<M: Model>(name: &str, model: &M, config: &M::Config) -> Result<(), BoxError> {
    let fx = Fixture::monthly()?;
    let run = RunInfo::with_periods(6);
    let t = Instant::now();
    let trained = model.train(config, TrainInput::new(&fx.train, &run, None))?;
    let train_time = t.elapsed();
    let t = Instant::now();
    let pred = model.predict(
        &trained,
        config,
        PredictInput::new(&fx.historic, &fx.future, &run, None),
    )?;
    let predict_time = t.elapsed();
    println!(
        "{name}: train {train_time:?}, predict {predict_time:?}, {} rows",
        pred.n_rows()
    );
    if let Some(path) = std::env::var_os("DEMO_OUTPUT") {
        std::fs::write(path, serde_json::to_vec(&pred)?)?;
    }
    let (tp, loc) = (
        pred.require(cols::TIME_PERIOD)?,
        pred.require(cols::LOCATION)?,
    );
    let samples: Vec<Vec<f64>> = pred
        .names()
        .iter()
        .filter(|n| n.starts_with("sample_"))
        .map(|n| pred.f64_column(n))
        .collect::<Result<_, _>>()?;
    for row in 0..pred.n_rows() {
        let mut v: Vec<f64> = samples.iter().filter_map(|s| s.get(row).copied()).collect();
        v.sort_by(f64::total_cmp);
        let median = v.get(v.len() / 2).copied().unwrap_or(f64::NAN);
        println!(
            "  {:<3} {}  median {median:>7.2}",
            loc.str_at(row).unwrap_or("?"),
            tp.str_at(row).unwrap_or("?")
        );
    }
    Ok(())
}
